def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1
    if len(counts) < 2:
        return [row[:] for row in grid]
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    mh, mw = r1-r0+1, c1-c0+1
    # Grow the rectangle by the marker's smaller dimension; the demonstrated
    # 4x3 marker uses a two-cell margin, while square markers use their side.
    thickness = min(mh, mw) - (1 if mh != mw else 0)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-thickness), min(h, r1+thickness+1)):
        for c in range(max(0, c0-thickness), min(w, c1+thickness+1)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = marker
    return out
