    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1
    if len(counts) < 2:
        return [row[:] for row in grid]
    marker = min(counts, key=counts.get)
    allpts = [(r, c) for r in range(h) for c in range(w) if grid[r][c]]
    r0, r1 = min(r for r,c in allpts), max(r for r,c in allpts)
    c0, c1 = min(c for r,c in allpts), max(c for r,c in allpts)
    mpts = [(r,c) for r,c in allpts if grid[r][c] == marker]
    mr0, mr1 = min(r for r,c in mpts), max(r for r,c in mpts)
    mc0, mc1 = min(c for r,c in mpts), max(c for r,c in mpts)
    mh, mw = mr1-mr0+1, mc1-mc0+1
    thickness = min(mh, mw) if mh == mw else max(1, min(mh, mw)-1)
    out = [row[:] for row in grid]
    for r in range(max(0,r0-thickness), min(h,r1+thickness+1)):
        for c in range(max(0,c0-thickness), min(w,c1+thickness+1)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = marker
